"""Independent regression tests for the documented powerful-integer rules."""

import random
import unittest

from src.component import count_powerful_integers


def brute_force(start, finish, limit, suffix):
    return sum(
        str(value).endswith(suffix)
        and all(int(digit) <= limit for digit in str(value))
        for value in range(max(1, start), finish + 1)
    )


class PowerfulIntegerTests(unittest.TestCase):
    def test_documented_examples(self):
        self.assertEqual(count_powerful_integers(1, 6000, 4, "124"), 5)
        self.assertEqual(count_powerful_integers(15, 215, 6, "10"), 2)
        self.assertEqual(count_powerful_integers(1000, 2000, 4, "3000"), 0)

    def test_boundaries(self):
        cases = [
            (124, 124, 4, "124", 1),
            (125, 1123, 4, "124", 0),
            (1124, 1124, 4, "124", 1),
            (1, 10**18, 4, "125", 0),
            (1, 999, 9, "1000", 0),
            (0, 0, 9, "1", 0),
            (-100, 11, 1, "1", 2),
            (100, 1, 9, "1", 0),
            (1, 1001, 1, "001", 1),
            (1, 1000, 1, "001", 0),
        ]
        for start, finish, limit, suffix, expected in cases:
            with self.subTest(case=(start, finish, limit, suffix)):
                self.assertEqual(
                    count_powerful_integers(start, finish, limit, suffix), expected
                )

    def test_exhaustive_small_upper_bounds(self):
        for suffix in ("1", "2", "9", "10", "11", "21", "100", "001"):
            for limit in range(1, 10):
                expected = 0
                for bound in range(501):
                    if bound > 0:
                        text = str(bound)
                        expected += text.endswith(suffix) and all(
                            int(digit) <= limit for digit in text
                        )
                    self.assertEqual(
                        count_powerful_integers(1, bound, limit, suffix), expected,
                        (bound, limit, suffix),
                    )

    def test_random_intervals_against_brute_force(self):
        randomizer = random.Random(950)
        for _ in range(2000):
            start = randomizer.randrange(-100, 10000)
            finish = start + randomizer.randrange(1000)
            limit = randomizer.randrange(1, 10)
            suffix = str(randomizer.randrange(1, 1000))
            self.assertEqual(
                count_powerful_integers(start, finish, limit, suffix),
                brute_force(start, finish, limit, suffix),
                (start, finish, limit, suffix),
            )

    def test_large_ranges(self):
        self.assertEqual(
            count_powerful_integers(1, 10**100 - 1, 1, "11"), 2**98
        )
        self.assertEqual(
            count_powerful_integers(1, 10**100 - 1, 9, "123"), 10**97
        )
        start, finish, suffix = 987654321012345, 987654321098765, 49
        expected = (finish - suffix) // 100 - (start - 1 - suffix) // 100
        self.assertEqual(
            count_powerful_integers(start, finish, 9, str(suffix)), expected
        )


if __name__ == "__main__":
    unittest.main()
